export const EXPANDED_INFERNO_ANUBIS_CACHE: UtilityReference[] = SOURCE_GUIDES.flatMap((row) => {
  const photos: UtilityPhoto[] = row.photos.map(([kind, image], index) => ({
    image, kind,
    caption: kind === "position" ? `Standing position · ${row.from}` : kind === "landing" ? "Landing result" : index > 1 ? "Aim detail" : "Crosshair alignment",
    creator: row.creator, source: row.source,
  }));
  return row.sides.map((side) => ({
    id: `expanded-cs2tricks-${row.mapId}-${row.slug}-${side.toLowerCase()}`,
    mapId: row.mapId, levelId: "main", side, type: row.type, title: row.title,
    from: row.from, target: row.target, purpose: `${row.type} from ${row.from} to ${row.target}.`,
    throwType: row.throwType, steps: row.steps, x: 500, y: 500, showMarker: false,
    userCreated: false, creator: row.creator, source: row.source,
    videoUrl: row.videoUrl, ...(row.videoFallbackUrl ? { videoFallbackUrl: row.videoFallbackUrl } : {}),
    ...(row.localPosition ? { photos } : { remotePhotos: photos }),
    tags: ["Photo guide", "Video guide", "CS2Tricks"],
  }));
});
